/bin/zsh -lc "python3 -B -c 'import csv,json,collections
from pathlib import Path
root=Path(\"cancer-dependency-rsi\")
pp=list(csv.DictReader((root/\"data/passports_model_list_20260921.csv\").open(encoding=\"utf-8-sig\",newline=\"\")))
byid={r[\"model_id\"]:r for r in pp}
assert len(byid)==len(pp)
def kind(r): return \"organoid\" if \"organoid\" in r[\"model_type\"].lower() else \"cell_line\" if \"cell line\" in r[\"model_type\"].lower() else \"other\"
byp=collections.defaultdict(list)
for r in pp:
    if r[\"patient_id\"]: byp[r[\"patient_id\"]].append(r)
pairs={p:ms for p,ms in byp.items() if {kind(m) for m in ms}>={\"organoid\",\"cell_line\"}}
direct=[]; chains=[]; missing=[]; cycles=[]; patient_disagreements=[]
for r in pp:
    seen={r[\"model_id\"]}; cur=r
    while cur[\"parent_id\"]:
        parent=cur[\"parent_id\"]
        if parent not in byid: missing.append((r[\"model_id\"],parent)); break
        if parent in seen: cycles.append((r[\"model_id\"],parent)); break
        seen.add(parent); anc=byid[parent]
        if {kind(r),kind(anc)}=={\"organoid\",\"cell_line\"}:
            chains.append((r[\"model_id\"],parent))
            if cur is r: direct.append((r[\"model_id\"],parent))
        if r[\"patient_id\"]"'!=anc["patient_id"]: patient_disagreements.append((r["model_id"],parent))
        cur=anc
print("Independent candidate patients/direct cross-type links/ancestor cross-type links:",len(pairs),len(direct),len(chains))
print("Missing parent refs/cycles/patient disagreements:",len(missing),len(cycles),len(patient_disagreements))
assert not pairs and not direct and not chains and not missing and not cycles and not patient_disagreements
print("NO PAIRING OR IDENTITY AMBIGUITIES FOUND IN PINNED SNAPSHOT")
'"'"

